export default function About() {
    const team = [
        { name: "Kapil chandel", role: "CEO&Founder", specialty: "AI Research" },
        { name: "Tushar chandel", role: "CTO&Co-Founder", specialty: "Cybersecurity" },
        { name: "Sanjay chandel", role: "Management Head", specialty: "finance&management" }
    ]

    return (
        <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-gray-900 py-20">
            <div className="container mx-auto px-6">
                <h1 className="text-5xl font-bold text-center mb-16 text-white">About Techodite</h1>

                <div className="max-w-3xl mx-auto text-center mb-16">
                    <p className="text-xl text-gray-300 leading-relaxed">
                        We are a team of cybersecurity experts and AI researchers dedicated to building
                        the future of digital protection.
                    </p>
                </div>

                <div className="grid md:grid-cols-3 gap-8">
                    {team.map((member, index) => (
                        <div key={index} className="bg-white/10 backdrop-blur-lg rounded-2xl p-8 text-center hover:bg-white/20 transition-all">
                            {(member.name === "Kapil chandel" || member.name === "Sanjay chandel" || member.name === "Tushar chandel") ? (
                                <img src={member.name === "Kapil chandel" ? "/kapil-chandel.jpg" : member.name === "Sanjay chandel" ? "/sanjay-chandel.jpg" : "/tushar-chandel.pdf"} alt={member.name} className="w-24 h-24 rounded-full mx-auto mb-4 object-cover" />
                            ) : (
                                <div className="w-24 h-24 bg-gradient-to-r from-cyan-500 to-blue-500 rounded-full mx-auto mb-4 flex items-center justify-center text-white text-2xl font-bold">
                                    {member.name.split(' ').map(n => n[0]).join('')}
                                </div>
                            )}
                            <h3 className="text-xl font-bold text-white mb-2">{member.name}</h3>
                            <p className="text-cyan-400 mb-2">{member.role}</p>
                            <p className="text-gray-300">{member.specialty}</p>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
}